diff --git a/src/common/cert_vfy.c b/src/common/cert_vfy.c
index ffdb76e..d8acbb0 100644
--- a/src/common/cert_vfy.c
+++ b/src/common/cert_vfy.c
@@ -521,8 +521,20 @@ int verify_signature(X509 * x509, unsigned char *data, int data_length,
   if (EVP_PKEY_base_id(pubkey) == EVP_PKEY_EC) {
     rs_len = *signature_length / 2;
     ec_sig = ECDSA_SIG_new();
+
+#if OPENSSL_VERSION_NUMBER < 0x30000000L
     BN_bin2bn(*signature, rs_len, ECDSA_SIG_get0_r(ec_sig));
     BN_bin2bn(*signature + rs_len, rs_len, ECDSA_SIG_get0_s(ec_sig));
+#else
+    BIGNUM *r = BN_bin2bn(*signature, rs_len, NULL);
+    BIGNUM *s = BN_bin2bn(*signature + rs_len, rs_len, NULL);
+
+    rv = ECDSA_SIG_set0(ec_sig, r, s);
+    if (rv != 1) {
+      set_error("ECDSA_SIG_set0() failed.");
+      return -1;
+    }
+#endif
     *signature_length = i2d_ECDSA_SIG(ec_sig, &p);
     free(*signature);
     *signature = malloc(*signature_length);
